export const BODY: string = "\n<p>تصویر تقسیم کرنا مختصر کام ہے: تصویر اپ لوڈ کریں، تقسیم کا طریقہ چنیں، کٹ لکیریں جانچیں، اور ٹکڑے ڈاؤن لوڈ کریں۔ یہ رہنما ہر مرحلہ ترتیب سے بتاتا ہے، پہلے اپ لوڈ سے لے کر تیار ٹائل تک۔</p>\n<p>شروع کرنے سے پہلے آپ کو صرف ایک چیز چاہیے: وہ تصویر جسے آپ تقسیم کرنا چاہتے ہیں۔ بڑی، اعلیٰ ریزولوشن ماخذ بہترین ٹائل دیتا ہے، کیونکہ ہر ٹائل مکمل اصل سائز پر کٹتا ہے۔ چھوٹا ماخذ چھوٹے ٹائل دیتا ہے، اس لیے اپنے پاس سب سے بڑی فائل استعمال کریں۔</p>\n<p><a href=\"/ur/tasveer-split-karein/\">تصویر اسپلٹر</a> کام آپ کے براؤزر میں کرتا ہے۔ کچھ بھی سرور پر اپ لوڈ نہیں ہوتا، کوئی اکاؤنٹ نہیں، اور ٹائل مفت ڈاؤن لوڈ ہوتے ہیں۔ نیچے کے مراحل پر عمل کریں اور چند منٹ میں آپ کے پاس تقسیم شدہ تصویر ہو گی۔</p>\n<h2 id=\"step-1-upload-your-image\">مرحلہ 1: اپنی تصویر اپ لوڈ کریں</h2>\n<p>اسپلٹر کھولیں اور اپنی تصویر اپ لوڈ والے حصے پر گھسیٹ دیں، یا اپنے آلے سے فائل چننے کے لیے اس پر کلک کریں۔ آپ Ctrl+V سے کلپ بورڈ سے تصویر سیدھی چسپاں بھی کر سکتے ہیں، جو ان اسکرین شاٹ کے لیے مفید ہے جنہیں آپ نے فائل کے طور پر محفوظ نہیں کیا۔</p>\n<p>ٹول 20 MB تک JPG، PNG، WebP، HEIC، GIF، BMP اور SVG فائلیں قبول کرتا ہے۔ زیادہ تر تصویریں اور اسکرین شاٹ اس حد سے کہیں نیچے ہیں۔ آئی فون کی HEIC تصویر کسی بھی دوسری فائل کی طرح اپ لوڈ اور تقسیم ہوتی ہے۔</p>\n<p>جیسے ہی تصویر لوڈ ہوتی ہے، ابتدائی 3 بہ 3 تقسیم خود بخود بن جاتی ہے۔ آپ کو گرڈ اور نمبر والی کٹ لکیریں پیش نظارے پر فوراً دکھائی دیں گی، جو آپ کو ایڈجسٹ کرنے کا نقطہ آغاز دیتی ہیں۔</p>\n<h2 id=\"step-2-choose-a-split-mode\">مرحلہ 2: تقسیم موڈ چنیں</h2>\n<p>تین موڈ میں سے ایک چنیں: Grid، Horizontal Strips، یا Vertical Strips۔ Grid تصویر کو قطاروں اور کالموں میں تقسیم کرتا ہے، اور یہ انسٹاگرام گرڈ، پزل اور پوسٹر کا موڈ ہے۔ اسے اس وقت چنیں جب ٹائل ساتھ بیٹھ کر تصویر دوبارہ بنائیں گے۔</p>\n<p>Horizontal Strips تصویر کو ڈھیر شدہ قطاروں میں کاٹتے ہیں۔ یہ موڈ لمبے اسکرین شاٹ، لمبی انفوگرافک، اور اوپر سے نیچے پڑھی جانے والی کسی بھی چیز کے لیے چنیں۔ ہر پٹی چوڑی، چھوٹی تصویر ہے جو اپنے طور پر صاف پرنٹ یا پوسٹ ہوتی ہے۔</p>\n<p>Vertical Strips تصویر کو ساتھ والی کالموں میں کاٹتے ہیں۔ یہ موڈ چوڑے پینوراما اور بینر کے لیے چنیں، جہاں ہر پٹی منظر کو دائیں جاری رکھتی ہے۔ عمودی پٹیوں میں تقسیم شدہ پینوراما سوائپ کرنے والے کیروسل کے طور پر کام کرتا ہے۔</p>\n<h2 id=\"step-3-set-rows-and-columns\">مرحلہ 3: قطاریں اور کالم طے کریں</h2>\n<p>Grid موڈ میں قطاروں اور کالموں کی تعداد طے کریں۔ تین قطاریں اور تین کالم کلاسک نو ٹائل انسٹاگرام گرڈ دیتے ہیں۔ دو بہ دو سادہ چار ٹائل تقسیم دیتا ہے، اور چار بہ چار بڑے پزل کے لیے سولہ ٹائل دیتا ہے۔</p>\n<p>چننے سے پہلے ٹائل سائز کے بارے میں سوچیں۔ 3000 پکسل تصویر 3 بہ 3 تقسیم سے 1000 پکسل ٹائل دیتی ہے، جو کہیں بھی پوسٹ کرنے کے لیے کافی بڑے ہیں۔ وہی تصویر 10 بہ 10 تقسیم سے 300 پکسل ٹائل دیتی ہے، جو چھوٹے ہیں اور صرف تھمب نیل یا موزیک کو سوٹ کرتے ہیں۔</p>\n<p>پٹی موڈ میں اس کی بجائے پٹیوں کی تعداد طے کریں۔ لمبے اسکرین شاٹ کے لیے چار افقی پٹیاں، پینوراما کے لیے تین عمودی پٹیاں، اور سادہ تقسیم کے لیے دو پٹیاں۔ پٹیاں تصویر کو برابر تقسیم کرتی ہیں، اس لیے گنتی ہر ٹکڑے کا سائز طے کرتی ہے۔</p>\n<h2 id=\"step-4-use-a-preset\">مرحلہ 4: پری سیٹ استعمال کریں</h2>\n<p>پری سیٹ عام تقسیم کے لیے ایک کلک ترتیبات ہیں۔ 3 بہ 3 انسٹاگرام گرڈ پری سیٹ وہ ہے جسے زیادہ تر لوگ چاہتے ہیں، اور ٹول میں عام گرڈ سائز اور پٹی گنتی کے لیے دوسرے بھی ہیں۔ پری سیٹ ٹیپ کریں اور قطاریں اور کالم خود بخود بھر جاتے ہیں۔</p>\n<p>پری سیٹ نقطہ آغاز ہے۔ اسے ٹیپ کرنے کے بعد عدد ایڈجسٹ کریں اگر آپ کی تصویر یا منصوبہ کو مختلف شکل چاہیے۔ پری سیٹ لکھنے کو بچاتا ہے، اور آپ حتمی تقسیم پر مکمل کنٹرول رکھتے ہیں۔</p>\n<p>جب آپ اکثر تصویریں تقسیم کریں تو پری سیٹ استعمال کریں۔ ہر ہفتے گرڈ بنانے والا سوشل میڈیا مینیجر ہر بار وہی پری سیٹ ٹیپ کر سکتا ہے اور ایک جیسے ٹائل سائز پا سکتا ہے، جو پروفائل گرڈ کو ایک پزل سے اگلے تک مستقل رکھتا ہے۔</p>\n<h2 id=\"step-5-inspect-the-cut-lines\">مرحلہ 5: کٹ لکیریں دیکھیں</h2>\n<p>پیش نظارہ دیکھیں اور نمبر والی کٹ لکیریں ڈھونڈیں۔ وہ بالکل دکھاتی ہیں کہ ہر ٹائل کہاں شروع اور کہاں ختم ہوتا ہے، اور عدد گرڈ میں ہر ٹائل کی جگہ بتاتے ہیں، بائیں سے دائیں اور اوپر سے نیچے پڑھتے ہوئے۔</p>\n<p>جانچیں کہ کوئی کٹ لکیر چہرے، متن کی لکیر، یا اہم تفصیل سے گزرتی ہے یا نہیں۔ دو ٹائل میں تقسیم شدہ چہرہ غلطی لگتا ہے، اور آدھا کٹا متن دونوں ٹائل میں ناقابل پڑھ ہے۔ اگر کٹ خراب جگہ پر پڑے تو گرڈ بدلیں یا تصویر دوبارہ رکھیں۔</p>\n<p>غیر مربع ماخذ کے لیے ٹائل شکلیں جانچیں۔ 3 بہ 3 تقسیم شدہ چوڑی تصویر چوڑے ٹائل دیتی ہے، مربع نہیں، اور وہ ٹائل مربع گرڈ کو سوٹ نہ کریں۔ قطاریں اور کالم ایڈجسٹ کریں، یا ماخذ کو پہلے مربع کراپ کریں، تاکہ ٹائل آپ کو چاہیے شکل میں نکلیں۔</p>\n<h2 id=\"step-6-choose-the-tile-format\">مرحلہ 6: ٹائل فارمیٹ چنیں</h2>\n<p>ٹائل کے لیے فارمیٹ چنیں۔ JPG تصویروں کو سوٹ کرتا ہے اور چھوٹی فائلیں دیتا ہے، جو سوشل پوسٹ اور ویب استعمال کے لیے آپ چاہتے ہیں۔ PNG گرافکس، متن اور شفافیت والی کسی بھی چیز کو سوٹ کرتا ہے، کیونکہ یہ ہر پکسل بالکل رکھتا ہے۔</p>\n<p>Tile Quality سلائیڈر JPG ٹائل کے لیے دکھائی دیتا ہے۔ یہ JPG آؤٹ پٹ کی کمپریشن کنٹرول کرتا ہے، اس لیے زیادہ ترتیب زیادہ تفصیل رکھتی ہے اور کم ترتیب چھوٹی فائلیں بناتی ہے۔ PNG ٹائل بغیر نقصان کے ہیں اور ان کا کوئی کوالٹی سلائیڈر نہیں۔</p>\n<p>شفاف PNG ماخذ کے لیے ٹائل فارمیٹ کے طور پر PNG چنیں۔ JPG میں شفافیت نہیں، اس لیے JPG کے طور پر برآمد شدہ شفاف ٹائل کو ٹھوس پس منظر ملتا ہے۔ شفافیت صرف اس فارمیٹ میں بچتی ہے جو اسے سپورٹ کرے۔</p>\n<h2 id=\"step-7-download-the-tiles\">مرحلہ 7: ٹائل ڈاؤن لوڈ کریں</h2>\n<p>ٹائل ایک ساتھ پانے کے لیے انہیں ZIP کے طور پر ڈاؤن لوڈ کریں۔ ZIP میں ہر ٹائل نمبر والی فائل کے طور پر ہے، اوپر بائیں کونے سے پڑھنے کی ترتیب میں۔ اسے ان زپ کریں اور سیٹ استعمال کے لیے تیار ہے، عدد بتاتے ہوئے کہ ہر ٹائل کہاں ہے۔</p>\n<p>اگر آپ کو صرف چند ٹائل چاہییں تو آپ انہیں ایک ایک کر کے بھی ڈاؤن لوڈ کر سکتے ہیں۔ پروفائل تصویر کے لیے ایک ٹائل یا بینر کے لیے ایک پٹی کو پورا سیٹ نہیں چاہیے، اور انفرادی ڈاؤن لوڈ ان زپ کرنے والا مرحلہ چھوڑ دیتا ہے۔</p>\n<p>ڈاؤن لوڈ کے بعد ٹائل ابعاد جانچیں۔ ایک ٹائل کھولیں اور تصدیق کریں کہ وہ آپ کے متوقع سائز کا ہے، خاص طور پر پرنٹ کام یا اسپرائٹ شیٹ کے لیے جہاں بالکل پکسل اہم ہیں۔ اب فوری جانچ استعمال سے پہلے غلط گرڈ ترتیب پکڑتی ہے۔</p>\n<h2 id=\"step-8-name-and-organize\">مرحلہ 8: نام دیں اور منظم کریں</h2>\n<p>ڈاؤن لوڈ شدہ ٹائل نمبر والے ہیں، مگر فائل نام عام ہیں۔ اگر کام کو بامعنی نام چاہییں تو انہیں دوبارہ نام دیں، جیسے puzzle-row-1 یا poster-tile-a1۔ واضح نام الجھن روکتے ہیں جب ایک فولڈر میں کئی تقسیم رہتی ہیں۔</p>\n<p>ہر تقسیم کو اپنے فولڈر میں رکھیں۔ کام کے نام والا فولڈر، اندر ترتیب سے ٹائل کے ساتھ، مختلف پراجیکٹ کی نمبر والی فائلوں سے بھرے ڈاؤن لوڈ فولڈر سے آسان ہے۔ تنظیم اس وقت سب سے اہم ہے جب گرڈ میں نو یا زیادہ ٹائل ہوں۔</p>\n<p>انسٹاگرام گرڈ کے لیے ٹائل کو پوسٹ کرنے کی ترتیب میں رکھیں، گرڈ ترتیب میں نہیں۔ پلیٹ فارم نئی پوسٹ پہلے دکھاتا ہے، اس لیے ٹائل آخری گرڈ جگہ سے پہلی تک پوسٹ ہونے چاہییں۔ پوسٹ کرنے کی ترتیب سے ترتیب دیا گیا فولڈر اندازہ ختم کرتا ہے۔</p>\n<h2 id=\"step-9-check-the-tiles\">مرحلہ 9: ٹائل جانچیں</h2>\n<p>چند ٹائل مکمل سائز پر کھولیں اور کنارے دیکھیں۔ ہر ٹائل کو پڑوسی ٹائل کا کوئی ٹکڑا اور سرحد کے ساتھ کوئی گم شدہ پٹی کے بغیر صاف کٹ دکھانا چاہیے۔ صاف تقسیم اس وقت نظر نہیں آتی جب ٹائل ساتھ بیٹھتے ہیں۔</p>\n<p>پہلے اور آخری ٹائل کو خاص طور پر جانچیں۔ کنارے والے ٹائل غیر برابر تقسیم کے مسائل ظاہر کرتے ہیں، جہاں تصویر ابعاد برابر تقسیم نہ ہوئے اور کنارے والے ٹائل ایک یا دو پکسل مختلف سائز کے نکلے۔ چھوٹا فرق عام ہے اور شاذ ہی نظر آتا ہے۔</p>\n<p>اگر کام گرڈ یا پزل ہے تو ٹائل کو ایک ساتھ دیکھیں۔ انہیں اسکرین پر ترتیب سے رکھیں، یا کولاج میں جوڑیں، اور تصدیق کریں کہ تصویر درست دوبارہ بنتی ہے۔ پورے سیٹ کے طور پر دیکھنے پر غلط جگہ والا ٹائل واضح ہوتا ہے۔</p>\n<h2 id=\"step-10-reuse-the-setup\">مرحلہ 10: سیٹ اپ دوبارہ استعمال کریں</h2>\n<p>کام آنے والی ترتیبات محفوظ کریں۔ گرڈ سائز، موڈ اور ٹائل فارمیٹ وہ تین عدد ہیں جو تقسیم طے کرتے ہیں، اور انہیں دوبارہ استعمال کرنے سے تقسیم کا سلسلہ مستقل رہتا ہے۔ انہی ترتیبات سے بنایا گیا ہفتہ وار گرڈ پزل سلسلہ لگتا ہے، حادثات کا سیٹ نہیں۔</p>\n<p>نئی تصویر کو انہی ترتیبات کے ساتھ تقسیم کریں، اسے اپ لوڈ کر کے اور وہی عدد لگا کر۔ ٹول وزٹ کے درمیان کچھ یاد نہیں رکھتا، اس لیے مرحلہ 8 میں بنایا گیا نوٹ ریکارڈ ہے۔ اسے پراجیکٹ فائلوں کے ساتھ رکھیں۔</p>\n<p>جب ماخذ شکل بدلے تو ترتیبات کو ایڈجسٹمنٹ چاہیے ہو سکتی ہے۔ مربع ماخذ اور چوڑا ماخذ 3 بہ 3 تقسیم سے مختلف ٹائل شکلیں دیتے ہیں، اس لیے عدد ایک جیسے ہونے پر بھی ہر بار پیش نظارہ جانچیں۔</p>\n<h2 id=\"fixing-uneven-splits\">غیر برابر تقسیم درست کرنا</h2>\n<p>غیر برابر تقسیم تب ہوتی ہے جب تصویر ابعاد قطاروں یا کالموں سے برابر تقسیم نہ ہوں۔ 1000 پکسل تصویر 3 کالموں میں تقسیم سے 333، 333 اور 334 پکسل کے ٹائل دیتی ہے، کیونکہ اضافی پکسل کہیں جانے چاہییں۔ کنارے والے ٹائل ایک پکسل بڑے ہو جاتے ہیں۔</p>\n<p>ایک پکسل کا فرق تقریباً ہر استعمال میں نظر نہیں آتا۔ سوشل پوسٹ، کیروسل اور پرنٹ لے آؤٹ اسے بغیر کسی نظر آنے والی سیون کے برداشت کرتے ہیں۔ مکمل تقسیم کے پیچھے نہ بھاگیں جب پکسل سطح کا فرق کوئی نظر آنے والا اثر نہ رکھے۔</p>\n<p>اسپرائٹ شیٹ جیسے پکسل مکمل کام کے لیے پہلے ماخذ تراشیں۔ تصویر کو ان ابعاد پر کراپ کریں جو گرڈ سے برابر تقسیم ہوں، پھر تقسیم کریں۔ 960 پکسل شیٹ 3 بہ 3 تقسیم سے بالکل 320 پکسل ٹائل دیتی ہے بغیر کوئی باقی بچے۔</p>\n<h2 id=\"splitting-for-a-specific-platform\">مخصوص پلیٹ فارم کے لیے تقسیم کرنا</h2>\n<p>ہر پلیٹ فارم کی اپنی ٹائل توقعات ہیں۔ انسٹاگرام گرڈ کو مربع ٹائل چاہییں، اس لیے ماخذ مربع ہونا چاہیے اور گرڈ 3 بہ 3 ہونا چاہیے۔ غیر مربع ماخذ غیر مربع ٹائل دیتا ہے جو پروفائل گرڈ توڑتے ہیں۔</p>\n<p>پرنٹ کو کاغذ سائز سے میل کھانے والے ٹائل چاہییں۔ A4 صفحوں کے لیے تقسیم شدہ پوسٹر کو A4 تناسب والے ٹائل چاہییں، اس لیے گرڈ کاغذ ابعاد سے طے کریں، گول عدد سے نہیں۔ ٹائل گنتی پوسٹر سائز کو صفحہ سائز سے تقسیم کرنے سے آتی ہے۔</p>\n<p>کیروسل کو ایسے ٹائل چاہییں جو اپنے طور پر پڑھیں۔ عمودی پٹیوں میں تقسیم شدہ پینوراما ایسی پٹیاں دیتا ہے جو ہر ایک منظر کا ٹکڑا دکھاتی ہیں، اور ہر ٹکڑا سوائپ روکنے کے لیے کافی دلچسپ ہونا چاہیے۔ صرف آسمان یا صرف خالی زمین والی پٹی سوائپ ضائع کرتی ہے۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: تقسیم چیک لسٹ</h2>\n<p>بڑا ماخذ اپ لوڈ کریں، Grid یا پٹی موڈ چنیں، قطاریں اور کالم طے کریں یا پری سیٹ ٹیپ کریں، اور چہرے اور متن کے لیے نمبر والی کٹ لکیریں دیکھیں۔ تصویروں کے لیے JPG اور شفافیت کے لیے PNG چنیں۔</p>\n<p>ZIP ڈاؤن لوڈ کریں، ٹائل ترتیب میں رکھیں، اور گرڈ ٹائل الٹی ترتیب میں پوسٹ کریں۔ اگر کٹ خراب جگہ پر پڑے یا ٹائل غیر برابر نکلیں تو گرڈ ایڈجسٹ کریں یا ماخذ تراشیں اور دوبارہ تقسیم کریں۔</p>\n<p>مکمل رہنما کے لیے <a href=\"/ur/blog/tasveer-splitter-rehnumai/\">Image Splitter: Complete Guide</a> پڑھیں، اور انسٹاگرام گرڈ کی تفصیل کے لیے <a href=\"/ur/blog/tasveer-split-karein-instagram-grid/\">Split Images for Instagram Grids and Puzzles</a> دیکھیں۔ اپنی تصویر <a href=\"/ur/tasveer-split-karein/\">تصویر اسپلٹر</a> سے تقسیم کریں۔</p>\n";

